import { useEffect, useState } from 'react';

// Hero heading: per-character rise behind an overflow mask.
export function CharRise({ text, delay = 0, stagger = 30, distance = 4, duration = 2 }) {
  const [on, setOn] = useState(false);
  useEffect(() => {
    const t = setTimeout(() => setOn(true), 30);
    return () => clearTimeout(t);
  }, []);
  const words = text.split(' ');
  let i = 0;
  return (
    <h1 aria-label={text} style={{ overflow: 'hidden', paddingBottom: '0.12em' }}>
      {words.map((word, w) => (
        <span key={w} aria-hidden="true" style={{ display: 'inline-block', whiteSpace: 'pre' }}>
          {[...(w < words.length - 1 ? word + '\u00a0' : word)].map((ch) => {
            const idx = i++;
            return (
              <span
                key={idx}
                style={{
                  display: 'inline-block',
                  opacity: on ? 1 : 0,
                  transform: on ? 'translateY(0px)' : 'translateY(' + distance + 'px)',
                  transition: 'opacity ' + duration + 's var(--ease-out-expo), transform ' + duration + 's var(--ease-out-expo)',
                  transitionDelay: delay + idx * stagger + 'ms',
                  willChange: 'opacity, transform'
                }}
              >
                {ch}
              </span>
            );
          })}
        </span>
      ))}
    </h1>
  );
}

import { motion } from 'motion/react';

const soft = [0.44, 0, 0.56, 1];

// Opacity-only load sequence under the hero heading. 0.001 (not 0) keeps nodes paint-eligible.
export function HeroSequence({ subline, primaryAction, secondaryAction }) {
  return (
    <div>
      <motion.p initial={{ opacity: 0.001 }} animate={{ opacity: 1 }} transition={{ delay: 0.4, duration: 1.2, ease: soft }}>
        {subline}
      </motion.p>
      <motion.div initial={{ opacity: 0.001 }} animate={{ opacity: 1 }} transition={{ delay: 0.6, duration: 1.2, ease: soft }}>
        {primaryAction}
        <motion.span style={{ display: 'inline-block' }} initial={{ opacity: 0.001 }} animate={{ opacity: 1 }} transition={{ delay: 1, duration: 0.4, ease: soft }}>
          {secondaryAction}
        </motion.span>
      </motion.div>
    </div>
  );
}

import { useRevealOnce } from './motion-presets';

// One observer on the container; children stagger by index.
export function RevealGrid({ items, distance = 24, duration = 1, stagger = 90, threshold = 0.15 }) {
  const [ref, shown] = useRevealOnce(threshold);
  return (
    <div ref={ref} className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4">
      {items.map((item, i) => (
        <div
          key={i}
          style={{
            opacity: shown ? 1 : 0,
            transform: shown ? 'translateY(0px)' : 'translateY(' + distance + 'px)',
            transition: 'opacity ' + duration + 's var(--ease-out-expo), transform ' + duration + 's var(--ease-out-expo)',
            transitionDelay: i * stagger + 'ms'
          }}
        >
          {item}
        </div>
      ))}
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import lottie from 'lottie-web';
import { useRevealOnce } from './motion-presets';

// Plays once when its card reveals, offset by the card's stagger slot.
export function InViewLottie({ src, index = 0, stagger = 90, loop = false }) {
  const box = useRef(null);
  const anim = useRef(null);
  const [ready, setReady] = useState(false);
  const [ref, shown] = useRevealOnce(0.15);
  useEffect(() => {
    const a = lottie.loadAnimation({ container: box.current, renderer: 'svg', loop: loop, autoplay: false, path: src, rendererSettings: { preserveAspectRatio: 'xMidYMid slice' } });
    anim.current = a;
    a.addEventListener('DOMLoaded', () => setReady(true));
    return () => a.destroy();
  }, [src, loop]);
  useEffect(() => {
    if (!shown || !ready) return;
    const a = anim.current;
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      a.goToAndStop(a.getDuration(true) - 1, true);
      return;
    }
    const t = setTimeout(() => a.goToAndPlay(0, true), Math.max(index * stagger, 120));
    return () => clearTimeout(t);
  }, [shown, ready, index, stagger]);
  return (
    <div ref={ref} style={{ position: 'relative', aspectRatio: '1 / 1' }}>
      <div ref={box} style={{ position: 'absolute', inset: 0 }} />
      {!ready && <div aria-hidden="true" style={{ position: 'absolute', inset: 0, background: 'var(--color-placeholder)' }} />}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useRevealOnce } from './motion-presets';

const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);

// Block grows from its bottom-left corner, markers and label fade in, then the number counts up.
export function StatBlock({ value = 100, suffix = '%', label, grow = 0.6, count = 1.2, countDelay = 0.3 }) {
  const [ref, shown] = useRevealOnce(0.3);
  const [n, setN] = useState(0);
  useEffect(() => {
    if (!shown) return;
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) { setN(value); return; }
    let raf;
    let start = null;
    const tick = (now) => {
      if (start === null) start = now;
      const t = now - start - countDelay * 1000;
      if (t < 0) { raf = requestAnimationFrame(tick); return; }
      const p = Math.min(t / (count * 1000), 1);
      setN(value * easeOutCubic(p));
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [shown, value, count, countDelay]);
  return (
    <div ref={ref} style={{ overflow: 'hidden' }}>
      <div style={{ position: 'relative', display: 'flex', transformOrigin: 'bottom left', transform: shown ? 'scale(1)' : 'scale(0.0001)', transition: 'transform ' + grow + 's var(--ease-out-expo)' }}>
        {['tl', 'tr', 'bl', 'br'].map((c) => (
          <span key={c} aria-hidden="true" className={'stat-marker stat-marker-' + c} style={{ opacity: shown ? 1 : 0, transition: 'opacity 0.3s ease ' + grow * 0.6 + 's' }} />
        ))}
        <span aria-hidden="true" style={{ fontVariantNumeric: 'tabular-nums' }}>{Math.round(n)}{suffix}</span>
        <span className="sr-only">{value}{suffix}</span>
        <span style={{ opacity: shown ? 1 : 0, transition: 'opacity 0.4s ease ' + grow * 0.5 + 's' }}>{label}</span>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { useRevealOnce } from './motion-presets';

const GLYPHS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*';
const rand = () => GLYPHS[Math.floor(Math.random() * GLYPHS.length)];
const scramble = (s) => [...s].map((c) => (c === ' ' ? ' ' : rand())).join('');
// speed 1..100 maps to 2500ms..300ms; the source uses 80 (about 744ms).
const durationFor = (speed) => 2500 - ((Math.min(100, Math.max(1, speed)) - 1) / 99) * 2200;

export function TypeOnText({ text, speed = 80, from = 'right', mode = 'typeOn', align = 'right' }) {
  const [ref, shown] = useRevealOnce(0.01);
  const [out, setOut] = useState(() => scramble(text));
  const raf = useRef(0);
  useEffect(() => {
    if (!shown) return;
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) { setOut(text); return; }
    let order = Array.from({ length: text.length }, (_, i) => i);
    if (from === 'right') order.reverse();
    if (from === 'center') {
      const mid = (text.length - 1) / 2;
      order.sort((a, b) => Math.abs(a - mid) - Math.abs(b - mid));
    }
    const dur = durationFor(speed);
    const t0 = performance.now();
    const step = (now) => {
      const p = Math.min(1, (now - t0) / dur);
      const done = new Set(order.slice(0, Math.floor(p * order.length)));
      let s = '';
      for (let i = 0; i < text.length; i++) {
        if (text[i] === ' ') s += ' ';
        else if (done.has(i)) s += text[i];
        else if (mode === 'scramble') s += rand();
      }
      setOut(s);
      if (p < 1) raf.current = requestAnimationFrame(step);
      else setOut(text);
    };
    raf.current = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf.current);
  }, [shown, text, speed, from, mode]);
  return (
    <p ref={ref} style={{ whiteSpace: 'pre-wrap', textAlign: align }}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true">{out}</span>
    </p>
  );
}

import { motion } from 'motion/react';

// Slides in from the left each time it is half visible; slides back out when it leaves.
export function SeparatorSlide({ children }) {
  return (
    <motion.div
      initial={{ x: -300 }}
      whileInView={{ x: 0 }}
      viewport={{ amount: 0.5, once: false }}
      transition={{ duration: 1, ease: [0.44, 0, 0.56, 1] }}
    >
      {children}
    </motion.div>
  );
}

