// Eased JS scroll for in-page anchors. Curve and duration match the observed profile (slow start, long settle).
export function smoothScrollTo(selector, offset = 0, duration = 850) {
  const el = document.querySelector(selector);
  if (!el) return;
  const startY = window.scrollY;
  const endY = el.getBoundingClientRect().top + startY - offset;
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    window.scrollTo(0, endY);
    return;
  }
  const ease = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
  const t0 = performance.now();
  const step = (now) => {
    const p = Math.min(1, (now - t0) / duration);
    window.scrollTo(0, startY + (endY - startY) * ease(p));
    if (p < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

document.addEventListener('click', (e) => {
