  if (!a) return;
  e.preventDefault();
  history.pushState(null, '', a.getAttribute('href'));
  smoothScrollTo(a.getAttribute('href'), 96);
});

import { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'motion/react';

const spring = { type: 'spring', duration: 0.4, bounce: 0.2 };

// In-place expanding nav panel. Bars rotate into a cross; the panel grows from the bar downwards.
export function MobileNav({ links, cta }) {
  const [open, setOpen] = useState(false);
  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, []);
  return (
    <header style={{ position: 'fixed', top: 0, left: 0, right: 0, zIndex: 10 }}>
      <div className="flex items-center justify-between">
        <a href="/" aria-label="Home" />
        <button
          type="button"
          aria-expanded={open}
          aria-controls="mobile-menu"
          aria-label={open ? 'Close menu' : 'Open menu'}
          onClick={() => setOpen(!open)}
          style={{ position: 'relative', width: 44, height: 44 }}
        >
          <motion.span className="menu-bar" animate={{ rotate: open ? 45 : 0, y: open ? 0 : -4 }} transition={spring} />
          <motion.span className="menu-bar" animate={{ rotate: open ? -45 : 0, y: open ? 0 : 4 }} transition={spring} />
        </button>
      </div>
      <AnimatePresence initial={false}>
        {open && (
          <motion.nav
            id="mobile-menu"
            aria-label="Main"
            style={{ overflow: 'hidden' }}
            initial={{ height: 0 }}
            animate={{ height: 'auto' }}
            exit={{ height: 0 }}
            transition={spring}
          >
            <ul>
              {links.map((l) => (
                <li key={l.href}>
                  <a href={l.href} onClick={() => setOpen(false)}>{l.label}</a>
                </li>
              ))}
            </ul>
            {cta}
          </motion.nav>
        )}
      </AnimatePresence>
    </header>
  );
}

