import { motion } from 'motion/react';

// phase: 'appear' at source, 'travel' to destination, 'settled' at destination.
export function TravellingChip({ phase, from, to, order = 0, children }) {
  const at = phase === 'appear' ? from : to;
  const transition =
    phase === 'appear'
      ? { opacity: { duration: 0.25, ease: 'easeOut' }, default: { duration: 0.3, ease: [0.2, 0.8, 0.2, 1] } }
      : phase === 'travel'
      ? { opacity: { duration: 0.2 }, default: { duration: 0.8, ease: [0.55, 0, 0.25, 1], delay: order * 0.08 } }
      : { opacity: { duration: 0.3, ease: 'easeOut', delay: 0.1 }, default: { duration: 0.3 } };
  return (
    <motion.div
      aria-hidden="true"
      style={{ position: 'absolute', left: 0, top: 0 }}
      initial={{ opacity: 0, x: from.x, y: from.y, scale: 0.92 }}
      animate={{ opacity: phase === 'settled' ? 0 : 1, x: at.x + (phase === 'appear' ? order * 4 : 0), y: at.y + (phase === 'appear' ? order * 4 : 0), scale: phase === 'settled' ? 0.94 : 1 }}
      transition={transition}
    >
      {children}
    </motion.div>
  );
}

