// motion-presets.jsx
import { useEffect, useRef, useState } from 'react';

export const soft = [0.44, 0, 0.56, 1];
export const outExpo = [0.16, 1, 0.3, 1];
export const springSoft = { type: 'spring', duration: 0.4, bounce: 0.2 };

export function prefersReducedMotion() {
  return typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

// One-shot reveal trigger shared by every scroll pattern.
export function useRevealOnce(threshold = 0.15) {
  const ref = useRef(null);
  const [shown, setShown] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (prefersReducedMotion()) { setShown(true); return; }
    const io = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) { setShown(true); io.disconnect(); }
    }, { threshold: threshold });
    io.observe(el);
    return () => io.disconnect();
  }, [threshold]);
  return [ref, shown];
}

// Framer Motion variants
export const fadeSoft = {
  hidden: { opacity: 0.001 },
  shown: (delay = 0) => ({ opacity: 1, transition: { delay: delay, duration: 1.2, ease: soft } })
};

export const riseExpo = {
  hidden: { opacity: 0, y: 24 },
  shown: (i = 0) => ({ opacity: 1, y: 0, transition: { duration: 1, ease: outExpo, delay: i * 0.09 } })
};

export const riseGrid = {
  hidden: { opacity: 0, y: 16 },
  shown: (i = 0) => ({ opacity: 1, y: 0, transition: { duration: 1.5, ease: outExpo, delay: i * 0.09 } })
};

export const springPop = {
  hidden: { opacity: 0.001, scale: 0.5, y: 50 },
  shown: { opacity: 1, scale: 1, y: 0, transition: springSoft }
};

export const separatorSlide = {
  hidden: { x: -300 },
  shown: { x: 0, transition: { duration: 1, ease: soft } }
};

export const buttonHover = { transition: springSoft };
export const compactHover = { transition: { duration: 0.2, ease: soft } };
export const iconSpin = { rest: { rotate: 0 }, hover: { rotate: 360, transition: { duration: 1, ease: soft } } };

