import { motion } from 'motion/react';

const spring = { type: 'spring', duration: 0.4, bounce: 0.2 };

export function PrimaryButton({ href, children }) {
  return (
    <motion.a
      href={href}
      className="inline-flex items-center justify-center"
      style={{ backgroundColor: 'var(--color-brand)' }}
      whileHover={{ backgroundColor: 'var(--color-brand-hover)' }}
      transition={spring}
    >
      {children}
    </motion.a>
  );
}

export function SecondaryButton({ href, children }) {
  return (
    <motion.a
      href={href}
      className="inline-flex items-center justify-center border"
      style={{ borderColor: 'var(--color-border)', color: 'var(--color-fg)' }}
      whileHover={{ borderColor: 'var(--color-brand)', color: 'var(--color-brand)' }}
      transition={spring}
    >
      {children}
    </motion.a>
  );
}

import { useRevealOnce } from './motion-presets';

// One observer on the container; children stagger by index.
export function RevealGrid({ items, distance = 24, duration = 1, stagger = 90, threshold = 0.15 }) {
  const [ref, shown] = useRevealOnce(threshold);
  return (
    <div ref={ref} className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4">
      {items.map((item, i) => (
        <div
          key={i}
          style={{
            opacity: shown ? 1 : 0,
            transform: shown ? 'translateY(0px)' : 'translateY(' + distance + 'px)',
            transition: 'opacity ' + duration + 's var(--ease-out-expo), transform ' + duration + 's var(--ease-out-expo)',
            transitionDelay: i * stagger + 'ms'
          }}
        >
          {item}
        </div>
      ))}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useRevealOnce } from './motion-presets';

const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);

// Block grows from its bottom-left corner, markers and label fade in, then the number counts up.
export function StatBlock({ value = 100, suffix = '%', label, grow = 0.6, count = 1.2, countDelay = 0.3 }) {
  const [ref, shown] = useRevealOnce(0.3);
  const [n, setN] = useState(0);
  useEffect(() => {
    if (!shown) return;
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) { setN(value); return; }
    let raf;
    let start = null;
    const tick = (now) => {
      if (start === null) start = now;
      const t = now - start - countDelay * 1000;
      if (t < 0) { raf = requestAnimationFrame(tick); return; }
      const p = Math.min(t / (count * 1000), 1);
      setN(value * easeOutCubic(p));
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [shown, value, count, countDelay]);
  return (
    <div ref={ref} style={{ overflow: 'hidden' }}>
      <div style={{ position: 'relative', display: 'flex', transformOrigin: 'bottom left', transform: shown ? 'scale(1)' : 'scale(0.0001)', transition: 'transform ' + grow + 's var(--ease-out-expo)' }}>
        {['tl', 'tr', 'bl', 'br'].map((c) => (
          <span key={c} aria-hidden="true" className={'stat-marker stat-marker-' + c} style={{ opacity: shown ? 1 : 0, transition: 'opacity 0.3s ease ' + grow * 0.6 + 's' }} />
        ))}
        <span aria-hidden="true" style={{ fontVariantNumeric: 'tabular-nums' }}>{Math.round(n)}{suffix}</span>
        <span className="sr-only">{value}{suffix}</span>
        <span style={{ opacity: shown ? 1 : 0, transition: 'opacity 0.4s ease ' + grow * 0.5 + 's' }}>{label}</span>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'motion/react';

const spring = { type: 'spring', duration: 0.4, bounce: 0.2 };

// In-place expanding nav panel. Bars rotate into a cross; the panel grows from the bar downwards.
export function MobileNav({ links, cta }) {
  const [open, setOpen] = useState(false);
  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, []);
  return (
    <header style={{ position: 'fixed', top: 0, left: 0, right: 0, zIndex: 10 }}>
      <div className="flex items-center justify-between">
        <a href="/" aria-label="Home" />
        <button
          type="button"
          aria-expanded={open}
          aria-controls="mobile-menu"
          aria-label={open ? 'Close menu' : 'Open menu'}
          onClick={() => setOpen(!open)}
          style={{ position: 'relative', width: 44, height: 44 }}
        >
          <motion.span className="menu-bar" animate={{ rotate: open ? 45 : 0, y: open ? 0 : -4 }} transition={spring} />
          <motion.span className="menu-bar" animate={{ rotate: open ? -45 : 0, y: open ? 0 : 4 }} transition={spring} />
        </button>
      </div>
      <AnimatePresence initial={false}>
        {open && (
          <motion.nav
            id="mobile-menu"
            aria-label="Main"
            style={{ overflow: 'hidden' }}
            initial={{ height: 0 }}
            animate={{ height: 'auto' }}
            exit={{ height: 0 }}
            transition={spring}
          >
            <ul>
              {links.map((l) => (
                <li key={l.href}>
                  <a href={l.href} onClick={() => setOpen(false)}>{l.label}</a>
                </li>
              ))}
            </ul>
            {cta}
          </motion.nav>
        )}
      </AnimatePresence>
    </header>
  );
}

import { useEffect, useRef, useState } from 'react';
import { useRevealOnce } from './motion-presets';

const GLYPHS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*';
const rand = () => GLYPHS[Math.floor(Math.random() * GLYPHS.length)];
const scramble = (s) => [...s].map((c) => (c === ' ' ? ' ' : rand())).join('');
// speed 1..100 maps to 2500ms..300ms; the source uses 80 (about 744ms).
const durationFor = (speed) => 2500 - ((Math.min(100, Math.max(1, speed)) - 1) / 99) * 2200;

export function TypeOnText({ text, speed = 80, from = 'right', mode = 'typeOn', align = 'right' }) {
  const [ref, shown] = useRevealOnce(0.01);
  const [out, setOut] = useState(() => scramble(text));
  const raf = useRef(0);
  useEffect(() => {
    if (!shown) return;
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) { setOut(text); return; }
    let order = Array.from({ length: text.length }, (_, i) => i);
    if (from === 'right') order.reverse();
    if (from === 'center') {
      const mid = (text.length - 1) / 2;
      order.sort((a, b) => Math.abs(a - mid) - Math.abs(b - mid));
    }
    const dur = durationFor(speed);
    const t0 = performance.now();
    const step = (now) => {
      const p = Math.min(1, (now - t0) / dur);
      const done = new Set(order.slice(0, Math.floor(p * order.length)));
      let s = '';
      for (let i = 0; i < text.length; i++) {
        if (text[i] === ' ') s += ' ';
        else if (done.has(i)) s += text[i];
        else if (mode === 'scramble') s += rand();
      }
      setOut(s);
      if (p < 1) raf.current = requestAnimationFrame(step);
      else setOut(text);
    };
    raf.current = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf.current);
  }, [shown, text, speed, from, mode]);
  return (
    <p ref={ref} style={{ whiteSpace: 'pre-wrap', textAlign: align }}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true">{out}</span>
    </p>
  );
}

import { useEffect, useState } from 'react';

// Declare STEPS outside the component so the array identity is stable.
export const STEPS = [500, 1050, 1550, 1950, 2750];

export function useScriptedLoop(steps, hold = 3200) {
  const [cycle, setCycle] = useState(0);
  const [step, setStep] = useState(0);
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener('change', onChange);
    return () => mq.removeEventListener('change', onChange);
  }, []);
  useEffect(() => {
    if (reduced) { setStep(steps.length); return; }
    setStep(0);
    const timers = steps.map((at, i) => setTimeout(() => setStep(i + 1), at));
    timers.push(setTimeout(() => setCycle((c) => c + 1), steps[steps.length - 1] + hold));
    return () => timers.forEach(clearTimeout);
  }, [cycle, reduced, steps, hold]);
  return { step, cycle, reduced };
}
